const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cincinnati = ee.Geometry.Point([-84.5120, 39.1031]); // Approximate center of Cincinnati, Ohio
  const scale = 1000; // Resolution in meters for reduceRegion

  const targetYear = 2018;
  const comparisonStartYear = 2010;
  const comparisonEndYear = 2017;
  const month = 2; // February

  // Define the ERA5-Land monthly temperature collection
  const era5Land = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY');
  const bandName = 'mean_2m_air_temperature'; // 2-meter air temperature in Kelvin

  let feb2018TempC = null;
  let comparisonTempsC = [];

  try {
    // 2. Data Acquisition & Check for 2018
    const feb2018Collection = era5Land
      .filterDate(`${targetYear}-0${month}-01`, `${targetYear}-0${month}-28`) // Use 28 as max day for Feb
      .filterBounds(cincinnati)
      .select(bandName);

    if (feb2018Collection.size().getInfo() === 0) {
      console.log("No data found for February 2018.");
      console.log("C1");
      return;
    }

    const feb2018Image = feb2018Collection.first();
    if (!feb2018Image) {
        console.log("No valid image for February 2018 after filtering.");
        console.log("C1");
        return;
    }

    // 3. Processing & Calculation for 2018
    const tempK_2018 = feb2018Image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: cincinnati,
      scale: scale,
      maxPixels: 1e9,
    }).get(bandName);

    // Convert Kelvin to Celsius
    const tempVal_2018 = await ee.data.computePromise(tempK_2018);
    if (tempVal_2018 === null || isNaN(tempVal_2018)) {
      console.log("Calculation for 2018 February temperature failed.");
      console.log("C3");
      return;
    }
    feb2018TempC = tempVal_2018 - 273.15;

    // 2. Data Acquisition & Check for comparison period (2010-2017)
    for (let year = comparisonStartYear; year <= comparisonEndYear; year++) {
      const collection = era5Land
        .filterDate(`${year}-0${month}-01`, `${year}-0${month}-28`)
        .filterBounds(cincinnati)
        .select(bandName);

      if (collection.size().getInfo() === 0) {
        // This is a warning, but we can proceed if other years exist
        console.log(`Warning: No data for February ${year}.`);
        continue;
      }

      const image = collection.first();
      if (!image) {
          console.log(`Warning: No valid image for February ${year} after filtering.`);
          continue;
      }

      // 3. Processing & Calculation for comparison year
      const tempK = image.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: cincinnati,
        scale: scale,
        maxPixels: 1e9,
      }).get(bandName);

      const tempVal = await ee.data.computePromise(tempK);
      if (tempVal !== null && !isNaN(tempVal)) {
        comparisonTempsC.push(tempVal - 273.15);
      } else {
        console.log(`Calculation for February ${year} temperature failed. Skipping.`);
      }
    }

    if (comparisonTempsC.length === 0) {
      console.log("No valid comparison temperatures found for 2010-2017.");
      // This could happen if all individual years failed, leading to an effective C1/C3 for the comparison period.
      console.log("C3"); // Or C1 if all collections were empty
      return;
    }

    const maxComparisonTempC = Math.max(...comparisonTempsC);

    // 5. Validation & Final Answer
    console.log(`Cincinnati February 2018 Temperature: ${feb2018TempC.toFixed(2)} °C`);
    console.log(`Max February Temperature (2010-2017): ${maxComparisonTempC.toFixed(2)} °C`);

    if (feb2018TempC === null || isNaN(feb2018TempC) || maxComparisonTempC === null || isNaN(maxComparisonTempC)) {
        console.log("C3");
    } else if (feb2018TempC > maxComparisonTempC) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during the analysis:", error);
    if (error.message.includes("does not exist") || error.message.includes("Bad or missing image, collection, or band name")) {
      console.log("D");
    } else {
      console.log("C3"); // Generic error during computation
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
